const EXPECTED_SOURCE_PATHS = Object.freeze([
  "packages/core/src/ir/semantics/portable-reference-body.ts",
  "packages/core/src/ir/semantics/semantic-clone.ts",
  "packages/core/src/ir/semantics/semantic-env-ownership.ts",
  "packages/core/src/ir/semantics/semantic-env.ts",
  "packages/core/src/runtime-envelope/internal-scheduler.ts"
]);
const EXPECTED_COMPILED_PATHS = Object.freeze([
  "ir/semantics/portable-reference-body.js",
  "ir/semantics/semantic-clone.js",
  "ir/semantics/semantic-env-ownership.js",
  "ir/semantics/semantic-env.js",
  "runtime-envelope/internal-scheduler.js"
]);

function exactRows(rows, expectedPaths) {
  return (
    Array.isArray(rows) &&
    rows.length === expectedPaths.length &&
    rows.every((row, index) =>
      row?.claim === CLAIM &&
      row.path === expectedPaths[index] &&
      /^[0-9a-f]{64}$/u.test(row.currentDigest) &&
      /^[0-9a-f]{64}$/u.test(row.expectedDigest) &&
      Array.isArray(row.replacements) &&
      row.replacements.length > 0
    )
  );
}

export function executionContextHardeningCompiledReconstruction(path) {
  return POST_EXECUTION_CONTEXT_HARDENING_COMPILED_RECONSTRUCTIONS.find((row) => row.path === path);
}

export function validateExecutionContextHardeningHistoricalTransition({
  transition = EXECUTION_CONTEXT_HARDENING_HISTORICAL_TRANSITION,
  sourceReconstructions = POST_EXECUTION_CONTEXT_HARDENING_SOURCE_RECONSTRUCTIONS,
  compiledReconstructions = POST_EXECUTION_CONTEXT_HARDENING_COMPILED_RECONSTRUCTIONS,
} = {}) {
  if (
    transition?.claim !== CLAIM ||
    transition.predecessorCommit !== PREDECESSOR_COMMIT ||
    transition.successorCommit !== SUCCESSOR_COMMIT ||
    JSON.stringify(transition.sourceManifest) !== '{"count":5,"digest":"248ede247415fe59b568f3a3867162aed54c2b97254030c4c987cee0a3a7b277"}' ||
    JSON.stringify(transition.compiledManifest) !== '{"count":5,"digest":"5cdf77951c6242bfe681b48ced7046d650362f6c9ab685b0ae3bf396c4deb8fb"}' ||
    JSON.stringify(transition.sourceEndpoints) !== '{"predecessor":"900877336497961243940c3ebd65aa602b0bfd6f15e26843c60a7353e2c350a2","successor":"a35742ca185635531b32f05519e5910c2c73e8303af43595e6f9e28ed33e8de6"}' ||
    JSON.stringify(transition.compiledEndpoints) !== '{"predecessor":"17fe054a337a90651c870246d1c5ea66b8f4075005dbc81df5e62222fa988d95","successor":"518efda7ff1dce3b687884f7078b19652c5e02ce95872c812af9cea8985b340f"}' ||
    JSON.stringify(transition.compiledInventory?.predecessor) !== '{"count":317,"digest":"34aa878fbfb82d4235547aed9abec7cd1d6c848f68d990ad9cba915d1def5d67"}' ||
    JSON.stringify(transition.compiledInventory?.successor) !== '{"count":317,"digest":"34aa878fbfb82d4235547aed9abec7cd1d6c848f68d990ad9cba915d1def5d67"}' ||
    !exactRows(sourceReconstructions, EXPECTED_SOURCE_PATHS) ||
    !exactRows(compiledReconstructions, EXPECTED_COMPILED_PATHS)
  ) {
    throw new TypeError('execution-context hardening historical transition immutable identity changed');
  }
  return true;
}
